Definition ul_exit (ra sp gp tp t0 t1 t2 s0 s1 a1 a4 a5 a6 a7 s2 s3 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (a0' a2' a3' s4' s5' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0' a1 a2' a3' a4 a5 a6 a7 s2 s3 s4' s5' s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x12a050) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma ul_rows : forall (k : nat) (i : Z)
    (ra gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem)
    (sp dh dwpl P DR dn : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 -> 0 < dwpl <= 2^24 ->
  0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> P mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  (forall i', 0 <= i' < dh -> DR <= P + 4 * (dwpl * i') /\ P + 4 * (dwpl * i') + 4 <= DR + dn) ->
  wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (ul_exit ra (Z_to_bv 64 sp) gp tp t0 t1 t2 s0 s1 a1 a4 a5 a6 a7 (Z_to_bv 64 (dwpl * 4)) (Z_to_bv 64 2147450880) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m DR dn)
    (MS (mkR ra (Z_to_bv 64 sp) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (P + 4 * (dwpl * i))) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (dwpl * 4)) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 (dh - i)) (Z_to_bv 64 (P + 4 * (dwpl * i))) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
